(()=>{window.DRV=(key,maxS)=>{const idx=D.findIndex(d=>d._key===key);PT8.launch({mode:'mp',rally:true,track:idx,laps:1,humans:[{id:'ford',alt:0}],ai:[]});const Rc=RACE;Rc.state='race';Rc.green=true;const c=Rc.cars.find(q=>q.human);c.forceAI=true;const T=Rc.T;const out=[];let maxLat=0,fall=0,minSp=1e9,stuck=0,lastU=0;
 for(let s=0;s<maxS;s++){step(1/60);const i=c.idx||0;const lat=Math.abs((c.x-T.x[i])*Math.cos(T.psi[i])-(c.z-T.z[i])*Math.sin(T.psi[i]));maxLat=Math.max(maxLat,lat);if(c.y<T.y[i]-6)fall++;
  if(s%300===0){out.push(Math.round(s/60)+'s u='+Math.round(c.unw)+'/'+T.finI+' sp='+Math.round(c.sp)+' lat='+lat.toFixed(1)+' dmg='+(c.dmg||0).toFixed(2));if(Math.abs(c.unw-lastU)<5)stuck++;lastU=c.unw}
  if(c.fin)break}
 return JSON.stringify({fin:!!c.fin,t:+(Rc.t||0).toFixed(1),finT:c.finT,maxLat:+maxLat.toFixed(1),fall,stuck,laps:Rc.laps,log:out})};return 1})()

(()=>{const idx=D.findIndex(d=>d._key==='terr');PT8.launch({mode:'mp',rally:true,track:idx,laps:1,humans:[{id:'ford',alt:0}],ai:[]});const Rc=RACE;Rc.state='race';Rc.green=true;const c=Rc.cars.find(q=>q.human);c.forceAI=true;const T=Rc.T;const o=[];
 o.push('N='+T.N+' start car '+c.x.toFixed(1)+','+c.z.toFixed(1)+','+c.y.toFixed(1)+' idx='+c.idx+' unw='+c.unw);
 for(const i of [0,3,10,T.N-1,T.N-4,T.N-10,T.N-20])o.push(i+': '+T.x[i].toFixed(1)+','+T.z[i].toFixed(1)+' y='+T.y[i].toFixed(1)+' hw='+T.hw[i].toFixed(1)+' psi='+T.psi[i].toFixed(2)+' terr='+T.terr(T.x[i],T.z[i]).toFixed(1));
 for(let s=0;s<180;s++){step(1/60);if(s%30==0)o.push('t'+s+' '+c.x.toFixed(1)+','+c.z.toFixed(1)+','+c.y.toFixed(1)+' sp='+c.sp.toFixed(1)+' idx='+c.idx+' yaw='+c.yaw.toFixed(2)+' in='+JSON.stringify(c.in))}
 return o.join('\n')})()
